var current=0;
(function(){var nav=$('stepNav'),bar=$('phaseBar');ORDER.forEach(function(p,k){var idx=steps.map(function(s,i){return s.phase===p?i:-1}).filter(function(i){return i>=0});if(!idx.length)return;var h=el('h4',null,PH[p].n);h.style.setProperty('--c',PH[p].c);nav.appendChild(h);idx.forEach(function(i){var b=el('button',null,'<span>'+esc(steps[i].name)+'</span><span class="tick"></span>');b.type='button';b.setAttribute('data-i',i);b.style.setProperty('--c',PH[p].c);b.style.setProperty('--t',PH[p].t);b.onclick=function(){go(i)};nav.appendChild(b)});var pb=el('button','phase','<span class="num">Phase '+(k+1)+'</span><strong>'+PH[p].n+'</strong><span class="what">'+PH[p].what+'</span><span class="bar" aria-hidden="true"><i></i></span><span class="sr pdone"></span>');pb.type='button';pb.setAttribute('data-p',p);pb.style.setProperty('--c',PH[p].c);pb.style.setProperty('--t',PH[p].t);pb.onclick=function(){go(idx[0])};bar.appendChild(pb)})})();
function refresh(){$('starCount').textContent=starSteps.filter(function(i){return st.done['s'+i]}).length;[].forEach.call($('stepNav').querySelectorAll('button'),function(b){var i=+b.getAttribute('data-i');b.querySelector('.tick').innerHTML=st.done['s'+i]?'✓<span class="sr"> completed</span>':'';if(i===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});[].forEach.call($('phaseBar').children,function(pb){var p=pb.getAttribute('data-p'),ss=starSteps.filter(function(i){return steps[i].phase===p}),n=ss.filter(function(i){return st.done['s'+i]}).length;pb.querySelector('i').style.width=(ss.length?100*n/ss.length:0)+'%';pb.querySelector('.pdone').textContent=', '+n+' of '+ss.length+' tasks complete';if(p===steps[current].phase)pb.setAttribute('aria-current','step');else pb.removeAttribute('aria-current')})}
function go(i,focus){if(focus===undefined)focus=true;stopSpeech();current=Math.max(0,Math.min(steps.length-1,i));var s=steps[current],p=s.phase,ps=steps.filter(function(x){return x.phase===p}),k=ps.indexOf(s)+1;secs.forEach(function(x,j){x.classList.toggle('active',j===current)});document.body.style.setProperty('--ph',PH[p].c);document.body.style.setProperty('--ph-tint',PH[p].t);$('where').textContent=PH[p].n+' phase: step '+k+' of '+ps.length;$('pos').textContent='Page '+(current+1)+' of '+steps.length;$('prev').disabled=current===0;var nx=steps[current+1];$('next').disabled=!nx;$('next').textContent=!nx?'Finished':nx.phase!==p?'Next: '+PH[nx.phase].n+' phase':'Next';st.current=current;save();refresh();(showHooks[current]||[]).forEach(function(f){f()});window.scrollTo({top:0,behavior:reduceMotion()?'auto':'smooth'});if(focus)secs[current].querySelector('h2').focus({preventScroll:true})}
$('prev').onclick=function(){go(current-1)};$('next').onclick=function(){go(current+1)};
applyPrefs();paint();go(st.current||0,false);
